// Tiny HTMX-like helper for this app. Supports hx-get/hx-post, hx-target,
// hx-swap=innerHTML|outerHTML|beforeend|afterbegin, hx-swap-oob, hx-include,
// hx-indicator, and the click/change/load/every/custom triggers used by Taskunity.
(function () {
  const triggerCleanups = new WeakMap();

  // Re-execute <script> tags inserted via innerHTML (which doesn't run them).
  function runScripts(container) {
    container.querySelectorAll('script').forEach(function (old) {
      var s = document.createElement('script');
      Array.from(old.attributes).forEach(function (a) { s.setAttribute(a.name, a.value); });
      s.textContent = old.textContent;
      old.parentNode.replaceChild(s, old);
    });
  }

  function dispatch(name, detail) {
    document.body.dispatchEvent(new CustomEvent(name, { bubbles: true, detail: detail || {} }));
  }

  function cleanupTriggers(root) {
    if (!root || !root.querySelectorAll) return;
    [root].concat(Array.from(root.querySelectorAll('[hx-trigger]'))).forEach(function (el) {
      const cleanups = triggerCleanups.get(el) || [];
      cleanups.forEach(function (cleanup) { cleanup(); });
      triggerCleanups.delete(el);
    });
  }

  function resolveTarget(el, selector) {
    if (!selector || selector === 'this') return el;
    if (selector.indexOf('closest ') === 0) return el.closest(selector.slice(8));
    return document.querySelector(selector);
  }

  function includedControls(el) {
    const include = (el.getAttribute('hx-include') || '').trim();
    if (!include) return [];
    if (include.indexOf('find ') === 0) {
      return Array.from(el.querySelectorAll(include.slice(5)));
    }
    return Array.from(document.querySelectorAll(include));
  }

  function appendValues(params, source) {
    if (!source) return;
    const controls = source.matches && source.matches('input, select, textarea, button[name]')
      ? [source]
      : Array.from(source.querySelectorAll('input, select, textarea, button[name]'));
    controls.forEach(function (control) {
      if (!control.name || control.disabled) return;
      if ((control.type === 'checkbox' || control.type === 'radio') && !control.checked) return;
      if (control.tagName === 'SELECT' && control.multiple) {
        Array.from(control.selectedOptions).forEach(function (option) {
          params.append(control.name, option.value);
        });
        return;
      }
      if (control.type !== 'file') params.append(control.name, control.value);
    });
  }

  function requestValues(el) {
    const params = new URLSearchParams();
    if (el.tagName === 'FORM' || (el.matches && el.matches('input, select, textarea, button[name]'))) {
      appendValues(params, el);
    }
    includedControls(el).forEach(function (source) { appendValues(params, source); });
    return params;
  }

  function requestBody(el) {
    const body = el.tagName === 'FORM' ? new FormData(el) : new FormData();
    includedControls(el).forEach(function (source) { appendValues(body, source); });
    return body;
  }

  function applyOutOfBandSwaps(html) {
    const template = document.createElement('template');
    template.innerHTML = html;
    template.content.querySelectorAll('[hx-swap-oob]').forEach(function (replacement) {
      const current = replacement.id ? document.getElementById(replacement.id) : null;
      replacement.removeAttribute('hx-swap-oob');
      if (!current) {
        replacement.remove();
        return;
      }
      cleanupTriggers(current);
      current.replaceWith(replacement);
      runScripts(replacement);
      initializeTriggers(replacement);
    });
    return template.innerHTML;
  }

  async function swapTarget(target, targetSel, swap, html, detail, el) {
    if (!target) return null;
    html = applyOutOfBandSwaps(html);
    let swappedTarget = target;
    if (swap === 'outerHTML') {
      const targetId = target.id;
      cleanupTriggers(target);
      target.outerHTML = html;
      swappedTarget = targetId
        ? document.getElementById(targetId)
        : (targetSel && targetSel !== 'this' ? document.querySelector(targetSel) : null);
      if (swappedTarget) {
        runScripts(swappedTarget);
        initializeTriggers(swappedTarget);
      }
    } else if (swap === 'beforeend') {
      target.insertAdjacentHTML('beforeend', html);
      runScripts(target);
      initializeTriggers(target);
    } else if (swap === 'afterbegin') {
      target.insertAdjacentHTML('afterbegin', html);
      runScripts(target);
      initializeTriggers(target);
    } else {
      cleanupTriggers(target);
      target.innerHTML = html;
      runScripts(target);
      initializeTriggers(target);
    }
    dispatch('htmx:afterSwap', {
      target: swappedTarget || target,
      elt: el,
      xhr: detail && detail.xhr ? detail.xhr : null
    });
    return swappedTarget;
  }

  async function submit(el, event) {
    if (event && event.preventDefault) event.preventDefault();
    const method = el.getAttribute('hx-post') ? 'POST' : 'GET';
    let url = el.getAttribute('hx-post') || el.getAttribute('hx-get');
    const targetSel = el.getAttribute('hx-target');
    const swap = el.getAttribute('hx-swap') || 'innerHTML';
    const indicatorSel = el.getAttribute('hx-indicator') || '';
    const target = resolveTarget(el, targetSel);
    const indicator = indicatorSel ? document.querySelector(indicatorSel) : null;
    const options = { method: method, headers: { 'HX-Request': 'true' } };
    const detail = { elt: el, target: target, shouldSwap: true, xhr: null };
    let afterRequestSent = false;
    dispatch('htmx:beforeRequest', detail);
    if (indicator) indicator.classList.add('htmx-request');
    if (method === 'POST') {
      options.body = requestBody(el);
    } else {
      const params = requestValues(el);
      const qs = params.toString();
      if (qs) url += (url.includes('?') ? '&' : '?') + qs;
    }
    try {
      const response = await fetch(url, options);
      detail.xhr = response;
      if (response.redirected) {
        window.location.href = response.url;
        return;
      }
      const html = await response.text();
      detail.xhr = { responseText: html, status: response.status };
      dispatch('htmx:beforeSwap', detail);
      if (detail.shouldSwap !== false) {
        await swapTarget(target, targetSel, swap, html, detail, el);
      }
      dispatch('htmx:afterRequest', detail);
      afterRequestSent = true;
    } catch (error) {
      detail.error = error;
      dispatch('htmx:responseError', detail);
    } finally {
      if (!afterRequestSent) dispatch('htmx:afterRequest', detail);
      if (indicator) indicator.classList.remove('htmx-request');
    }
  }

  function durationMs(spec, fallback) {
    const match = spec.match(/(?:delay:|every\s+)(\d+(?:\.\d+)?)(ms|s|m)?/);
    if (!match) return fallback;
    const unit = match[2] || 'ms';
    const multiplier = unit === 'm' ? 60000 : (unit === 's' ? 1000 : 1);
    return Number(match[1]) * multiplier;
  }

  function initializeTriggers(root) {
    if (!root || !root.querySelectorAll) return;
    const elements = [];
    if (root.matches && root.matches('[hx-trigger]')) elements.push(root);
    elements.push.apply(elements, root.querySelectorAll('[hx-trigger]'));
    elements.forEach(function (el) {
      if (triggerCleanups.has(el)) return;
      const cleanups = [];
      (el.getAttribute('hx-trigger') || '').split(',').forEach(function (rawSpec) {
        const spec = rawSpec.trim();
        if (!spec || /^(click|change|submit)(?:\s|$)/.test(spec)) return;
        if (spec.indexOf('load') === 0) {
          const timer = window.setTimeout(function () {
            if (el.isConnected) submit(el);
          }, durationMs(spec, 0));
          cleanups.push(function () { window.clearTimeout(timer); });
          return;
        }
        if (spec.indexOf('every ') === 0) {
          const timer = window.setInterval(function () {
            if (el.isConnected) submit(el);
          }, durationMs(spec, 1000));
          cleanups.push(function () { window.clearInterval(timer); });
          return;
        }
        const eventName = spec.split(/\s+/)[0];
        const fromMatch = spec.match(/\bfrom:([^\s]+)/);
        const source = fromMatch
          ? (fromMatch[1] === 'body' ? document.body : document.querySelector(fromMatch[1]))
          : el;
        if (!source) return;
        const listener = function (event) {
          if (el.isConnected) submit(el, event);
        };
        source.addEventListener(eventName, listener);
        cleanups.push(function () { source.removeEventListener(eventName, listener); });
      });
      triggerCleanups.set(el, cleanups);
    });
  }

  window.htmx = window.htmx || {};
  window.htmx.ajax = async function (method, url, opts) {
    const options = opts || {};
    const swap = options.swap || 'innerHTML';
    const targetSel = typeof options.target === 'string' ? options.target : '';
    const target = targetSel ? document.querySelector(targetSel) : null;
    const detail = { elt: null, target: target, shouldSwap: true, xhr: null };
    dispatch('htmx:beforeRequest', detail);
    try {
      const response = await fetch(url, {
        method: (method || 'GET').toUpperCase(),
        headers: { 'HX-Request': 'true' }
      });
      if (response.redirected) {
        window.location.href = response.url;
        return;
      }
      const html = await response.text();
      detail.xhr = { responseText: html, status: response.status };
      dispatch('htmx:beforeSwap', detail);
      if (detail.shouldSwap !== false) {
        await swapTarget(target, targetSel, swap, html, detail, null);
      }
    } catch (error) {
      detail.error = error;
      dispatch('htmx:responseError', detail);
    } finally {
      dispatch('htmx:afterRequest', detail);
    }
  };
  window.htmx.trigger = function (target, name) {
    if (target) target.dispatchEvent(new CustomEvent(name, { bubbles: true }));
  };

  document.addEventListener('click', function (event) {
    const el = event.target.closest('[hx-get]:not(form), [hx-post]:not(form)');
    if (el) submit(el, event);
  });
  document.addEventListener('submit', function (event) {
    const el = event.target.closest('form[hx-get], form[hx-post]');
    if (el) submit(el, event);
  });
  document.addEventListener('change', function (event) {
    const self = event.target.closest('[hx-trigger~="change"]');
    if (self && (self.getAttribute('hx-get') || self.getAttribute('hx-post'))) {
      submit(self, event);
      return;
    }
    const form = event.target.closest('form[hx-trigger~="change"]');
    if (form) submit(form, event);
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { initializeTriggers(document); });
  } else {
    initializeTriggers(document);
  }
})();
